9	import { FormattedMessage } from 'react-intl';
10	import { useState } from 'react';
11	import { CopyButton } from '@mlflow/mlflow/src/shared/building_blocks/CopyButton';
12	import { CodeSnippet } from '@databricks/web-shared/snippet';
