14	type Provider = 'openai' | 'anthropic' | 'gemini';
15	type Language = 'curl' | 'python';
16	
17	interface EndpointUsageModalProps {
18	  open: boolean;
19	  onClose: () => void;
20	  endpointName: string;
21	  baseUrl?: string;
22	}
23	
24	const getBaseUrl = (baseUrl?: string): string => {
25	  if (baseUrl) return baseUrl;
26	  if (typeof window !== 'undefined') {
27	    return window.location.origin;
28	  }
29	  return 'http://localhost:5000';
30	};
31	
32	export const EndpointUsageModal = ({ open, onClose, endpointName, baseUrl }: EndpointUsageModalProps) => {
33	  const { theme } = useDesignSystemTheme();
34	  const [activeTab, setActiveTab] = useState<'unified' | 'passthrough'>('unified');
35	  const [selectedProvider, setSelectedProvider] = useState<Provider>('openai');
36	  const [selectedLanguage, setSelectedLanguage] = useState<Language>('curl');
37	  const [unifiedLanguage, setUnifiedLanguage] = useState<Language>('curl');
38	  const base = getBaseUrl(baseUrl);
39	  const mlflowInvocationsCurlExample = `curl -X POST ${base}/gateway/${endpointName}/mlflow/invocations \\
40	  -H "Content-Type: application/json" \\
41	  -d '{
42	  "messages": [
43	    {"role": "user", "content": "Hello, how are you?"}
44	  ]
45	}'`;
46	
47	  const mlflowInvocationsPythonExample = `import requests
48	
49	response = requests.post(
50	    "${base}/gateway/${endpointName}/mlflow/invocations",
51	    json={
52	        "messages": [
53	            {"role": "user", "content": "Hello, how are you?"}
54	        ]
55	    }
56	)
57	print(response.json())`;
58	
59	  const openaiChatCurlExample = `curl -X POST ${base}/gateway/mlflow/v1/chat/completions \\
60	  -H "Content-Type: application/json" \\
61	  -d '{
62	  "model": "${endpointName}",
63	  "messages": [
64	    {"role": "user", "content": "How are you?"}
65	  ]
66	}'`;
67	
68	  const openaiChatPythonExample = `from openai import OpenAI
69	
70	client = OpenAI(
71	    base_url="${base}/gateway/mlflow/v1",
72	    api_key="",  # API key not needed, configured server-side
73	)
74	
75	messages = [{"role": "user", "content": "How are you?"}]
76	
77	response = client.chat.completions.create(
78	    model="${endpointName}",  # Endpoint name as model
79	    messages=messages,
80	)
81	print(response.choices[0].message)`;
82	
83	  const openaiPassthroughCurlExample = `curl -X POST ${base}/gateway/openai/v1/responses \\
84	  -H "Content-Type: application/json" \\
85	  -d '{
86	  "model": "${endpointName}",
87	  "input": "How are you?"
88	}'`;
89	
90	  const openaiPassthroughPythonExample = `from openai import OpenAI
91	
92	client = OpenAI(
93	    base_url="${base}/gateway/openai/v1",
94	    api_key="dummy",  # API key not needed, configured server-side
95	)
96	
97	response = client.responses.create(
98	    model="${endpointName}",
99	    input="How are you?",
100	)
101	print(response.output_text)`;
102	
103	  const anthropicPassthroughCurlExample = `curl -X POST ${base}/gateway/anthropic/v1/messages \\
104	  -H "Content-Type: application/json" \\
105	  -d '{
106	  "model": "${endpointName}",
107	  "max_tokens": 1024,
108	  "messages": [
109	    {"role": "user", "content": "How are you?"}
110	  ]
111	}'`;
112	
113	  const anthropicPassthroughPythonExample = `import anthropic
114	
115	client = anthropic.Anthropic(
116	    base_url="${base}/gateway/anthropic",
117	    api_key="dummy",  # API key not needed, configured server-side
118	)
119	
120	response = client.messages.create(
121	    model="${endpointName}",
122	    max_tokens=1024,
123	    messages=[{"role": "user", "content": "How are you?"}],
124	)
125	print(response.content[0].text)`;
126	
127	  const geminiPassthroughCurlExample = `curl -X POST ${base}/gateway/gemini/v1beta/models/${endpointName}:generateContent \\
128	  -H "Content-Type: application/json" \\
129	  -d '{
130	  "contents": [{
131	    "parts": [{"text": "How are you?"}]
132	  }]
133	}'`;
134	
135	  const geminiPassthroughPythonExample = `from google import genai
136	
137	# Configure with custom endpoint
138	client = genai.Client(
139	    api_key='dummy',
140	    http_options={
141	        'base_url': "${base}/gateway/gemini",
142	    }
143	)
144	response = client.models.generate_content(
145	    model="${endpointName}",
146	    contents={'text': 'How are you?'},
147	)
148	client.close()
149	print(response.candidates[0].content.parts[0].text)`;
150	
151	  const renderCodeExample = (label: string, code: string, language: 'text' | 'python' = 'text') => (
152	    <div css={{ marginBottom: theme.spacing.md }}>
153	      <div
154	        css={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: theme.spacing.xs }}
155	      >
156	        <Typography.Text bold>{label}</Typography.Text>
157	        <CopyButton
158	          componentId="codegen_mlflow_app_src_oss_gateway_components_endpoints_EndpointUsageModal.tsx_147"
