1	import { describe, test, expect, jest } from '@jest/globals';
2	import { renderWithDesignSystem, screen } from '../../../common/utils/TestUtils.react18';
3	import { EndpointUsageModal } from './EndpointUsageModal';
4	
5	describe('EndpointUsageModal', () => {
6	  const defaultProps = {
7	    open: true,
8	    onClose: jest.fn(),
9	    endpointName: 'test-endpoint',
10	    baseUrl: 'http://localhost:5000',
11	  };
12	
13	  test('renders modal with title when open', () => {
14	    renderWithDesignSystem(<EndpointUsageModal {...defaultProps} />);
15	
16	    expect(screen.getByText('Query endpoint')).toBeInTheDocument();
17	  });
18	
19	  test('does not render modal when closed', () => {
20	    renderWithDesignSystem(<EndpointUsageModal {...defaultProps} open={false} />);
21	
22	    expect(screen.queryByText('Query endpoint')).not.toBeInTheDocument();
23	  });
24	
25	  test('renders unified APIs tab by default', () => {
26	    renderWithDesignSystem(<EndpointUsageModal {...defaultProps} />);
27	
28	    expect(screen.getByText('MLflow Invocations API')).toBeInTheDocument();
29	    expect(screen.getByText('OpenAI-Compatible Chat Completions API')).toBeInTheDocument();
30	  });
31	
32	  test('renders language selector in unified APIs tab', () => {
33	    renderWithDesignSystem(<EndpointUsageModal {...defaultProps} />);
34	
35	    // Verify language selector is rendered with both options
36	    expect(screen.getByRole('radio', { name: /cURL/ })).toBeInTheDocument();
37	    expect(screen.getByRole('radio', { name: /Python/ })).toBeInTheDocument();
38	
39	    // cURL is selected by default - shows curl content for both API sections
40	    expect(screen.getByRole('radio', { name: /cURL/ })).toBeChecked();
41	    const curlElements = screen.getAllByText(/curl -X POST/);
42	    expect(curlElements.length).toBe(2); // MLflow Invocations and OpenAI-Compatible both show cURL
43	  });
44	
45	  test('shows code examples with endpoint name in unified APIs', () => {
46	    renderWithDesignSystem(<EndpointUsageModal {...defaultProps} />);
47	
48	    // The endpoint name appears in multiple code examples, so use getAllByText
49	    const matchingElements = screen.getAllByText(/gateway\/test-endpoint\/mlflow\/invocations/);
50	    expect(matchingElements.length).toBeGreaterThan(0);
51	  });
52	
53	  test('switches to passthrough APIs tab when clicked', async () => {
54	    const userEvent = (await import('@testing-library/user-event')).default;
55	
56	    renderWithDesignSystem(<EndpointUsageModal {...defaultProps} />);
57	
58	    await userEvent.click(screen.getByText('Passthrough APIs'));
59	
60	    expect(screen.getByText('Provider')).toBeInTheDocument();
61	    expect(screen.getByText('OpenAI')).toBeInTheDocument();
62	    expect(screen.getByText('Anthropic')).toBeInTheDocument();
63	    expect(screen.getByText('Google Gemini')).toBeInTheDocument();
64	  });
65	
66	  test('shows OpenAI passthrough example by default in passthrough tab', async () => {
67	    const userEvent = (await import('@testing-library/user-event')).default;
68	
69	    renderWithDesignSystem(<EndpointUsageModal {...defaultProps} />);
70	
71	    await userEvent.click(screen.getByText('Passthrough APIs'));
72	
73	    expect(
74	      screen.getByText(
75	        "Direct access to OpenAI's Responses API for multi-turn conversations with vision and audio capabilities.",
76	      ),
77	    ).toBeInTheDocument();
78	    expect(screen.getByText(/gateway\/openai\/v1\/responses/)).toBeInTheDocument();
79	  });
80	
81	  test('renders provider selector in passthrough tab', async () => {
82	    const userEvent = (await import('@testing-library/user-event')).default;
83	
84	    renderWithDesignSystem(<EndpointUsageModal {...defaultProps} />);
85	
86	    await userEvent.click(screen.getByText('Passthrough APIs'));
87	
88	    // Verify provider selector is rendered with all options
89	    expect(screen.getByRole('radio', { name: /OpenAI/ })).toBeInTheDocument();
90	    expect(screen.getByRole('radio', { name: /Anthropic/ })).toBeInTheDocument();
91	    expect(screen.getByRole('radio', { name: /Google Gemini/ })).toBeInTheDocument();
92	
93	    // OpenAI is selected by default
94	    expect(screen.getByRole('radio', { name: /OpenAI/ })).toBeChecked();
95	  });
96	
97	  test('renders language selector in passthrough tab', async () => {
98	    const userEvent = (await import('@testing-library/user-event')).default;
99	
100	    renderWithDesignSystem(<EndpointUsageModal {...defaultProps} />);
101	
102	    await userEvent.click(screen.getByText('Passthrough APIs'));
103	
104	    // Verify language selector is rendered with both options
105	    expect(screen.getByRole('radio', { name: /cURL/ })).toBeInTheDocument();
106	    expect(screen.getByRole('radio', { name: /Python/ })).toBeInTheDocument();
107	
108	    // cURL is selected by default and shows curl content
109	    expect(screen.getByRole('radio', { name: /cURL/ })).toBeChecked();
110	    expect(screen.getByText(/curl -X POST/)).toBeInTheDocument();
111	  });
112	
113	  test('uses window.location.origin when baseUrl is not provided', () => {
114	    const originalLocation = window.location;
115	    Object.defineProperty(window, 'location', {
116	      value: { origin: 'http://custom-origin:8080' },
117	      writable: true,
118	    });
119	
120	    renderWithDesignSystem(<EndpointUsageModal open onClose={jest.fn()} endpointName="my-endpoint" />);
121	
122	    // The URL should appear in multiple code examples, so use getAllByText
123	    const matchingElements = screen.getAllByText(/http:\/\/custom-origin:8080\/gateway\/my-endpoint/);
124	    expect(matchingElements.length).toBeGreaterThan(0);
125	
126	    Object.defineProperty(window, 'location', { value: originalLocation, writable: true });
127	  });
128	
129	  test('renders copy buttons for code examples', () => {
130	    renderWithDesignSystem(<EndpointUsageModal {...defaultProps} />);
131	
132	    const copyButtons = screen.getAllByRole('button');
133	    expect(copyButtons.length).toBeGreaterThan(0);
134	  });
135	});
