function createWrapper() {
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false }, mutations: { retry: false } },
  });
  return ({ children }: { children: React.ReactNode }) => (
    <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
  );
}

describe('useTryIt scratch', () => {
  beforeEach(() => jest.clearAllMocks());

  test('success pretty-prints response', async () => {
    mockFetchOrFail.mockResolvedValue({ text: async () => '{"a":1}' } as any);
    const { result } = renderHook(() => useTryIt({ tryItRequestUrl: 'http://x/gateway/e/mlflow/invocations' }), {
      wrapper: createWrapper(),
    });
    act(() => result.current.sendRequest('{"messages": []}'));
    await waitFor(() => expect(result.current.data).toBe('{\n  "a": 1\n}'));
    expect(mockFetchOrFail).toHaveBeenCalledWith(
      'http://x/gateway/e/mlflow/invocations',
      expect.objectContaining({ method: 'POST', headers: { 'Content-Type': 'application/json' } }),
    );
    expect(result.current.error).toBeUndefined();
  });

  test('invalid JSON does not call fetch', async () => {
    const { result } = renderHook(() => useTryIt({ tryItRequestUrl: 'http://x' }), { wrapper: createWrapper() });
    act(() => result.current.sendRequest('not json'));
    await waitFor(() => expect(result.current.error?.message).toBe('Invalid JSON in request body'));
    expect(mockFetchOrFail).not.toHaveBeenCalled();
    expect(result.current.error?.responseBody).toBeUndefined();
  });

  test('NetworkRequestError sets message and responseBody', async () => {
    const err = new GenericNetworkRequestError({ status: 400 });
    (err as any).response = { text: async () => '{"error":"bad"}' };
    mockFetchOrFail.mockRejectedValue(err);
    const { result } = renderHook(() => useTryIt({ tryItRequestUrl: 'http://x' }), { wrapper: createWrapper() });
    act(() => result.current.sendRequest('{}'));
    await waitFor(() => expect(result.current.error?.message).toBe('A network error occurred.'));
    expect(result.current.error?.responseBody).toBe('{\n  "error": "bad"\n}');
  });

  test('generic error sets message only', async () => {
    mockFetchOrFail.mockRejectedValue(new Error('boom'));
    const { result } = renderHook(() => useTryIt({ tryItRequestUrl: 'http://x' }), { wrapper: createWrapper() });
    act(() => result.current.sendRequest('{}'));
    await waitFor(() => expect(result.current.error?.message).toBe('boom'));
    expect(result.current.error?.responseBody).toBeUndefined();
  });

  test('reset clears data and error', async () => {
    mockFetchOrFail.mockResolvedValue({ text: async () => '{"a":1}' } as any);
    const { result } = renderHook(() => useTryIt({ tryItRequestUrl: 'http://x' }), { wrapper: createWrapper() });
    act(() => result.current.sendRequest('{}'));
    await waitFor(() => expect(result.current.data).toBeDefined());
    act(() => result.current.reset());
    await waitFor(() => expect(result.current.data).toBeUndefined());
    expect(result.current.error).toBeUndefined();
  });
});
